import { VxeUI } from "@vxe-ui/core";
import VxeLoadingComponent from "./src/loading";
import { dynamicApp, dynamicStore, checkDynamic } from "../dynamics";
const VxeLoading = Object.assign({}, VxeLoadingComponent, {
  install(app) {
    app.component(VxeLoadingComponent.name, VxeLoadingComponent);
  }
});
const LoadingController = {
  open(options) {
    const opts = Object.assign({}, options);
    dynamicStore.globalLoading = Object.assign(
      {
        modelValue: true,
        text: opts.text,
        icon: opts.icon
      },
      { key: "gl" }
    );
    checkDynamic();
    return Promise.resolve();
  },
  close() {
    dynamicStore.globalLoading = null;
    return Promise.resolve();
  }
};
dynamicApp.use(VxeLoading);
VxeUI.component(VxeLoadingComponent);
VxeUI.loading = LoadingController;
const Loading = VxeLoading;
var loading_default = VxeLoading;
export {
  Loading,
  LoadingController,
  VxeLoading,
  loading_default as default
};
